    def __repr__(self):
        cn = self.__class__.__name__
        args = ', '.join(repr(s) for s in self.subspecs)
        extra = ''
        if self.default is not _MISSING:
            extra += ', default=%r' % (self.default,)
        if self.default_factory is not _MISSING:
            extra += ', default_factory=%r' % (self.default_factory,)
        if self.skip is not _MISSING:
            extra += ', skip=%r' % (self.skip,)
        if self.skip_exc is not GlomError:
            extra += ', skip_exc=%r' % (self.skip_exc,)
        return '%s(%s%s)' % (cn, args, extra)
